"""faxconsole.pbx — PBX status readers.

Port of read_trunk (legacy e:1009–1021), read_calls (legacy e:1024–1104),
and read_sip_endpoints (legacy e:1108–1136).

Each function accepts a ``transport`` (faxcli.transport.Transport) and an
optional ``vty_fn`` (read_calls only).  They return dicts with the same
shape as the legacy functions so the old page keeps working.

The cellular-core instrument in read_calls is behind an optional injected
callable ``vty_fn(msc_vty, command) -> str`` that defaults to "not probed"
(returns None), preserving the legacy meaning of a failed Reading.
"""
from __future__ import annotations

import re
from collections.abc import Callable
from typing import Any

from faxcli.transport import Transport


def read_trunk(transport: Transport) -> dict[str, Any]:
    """Port of legacy read_trunk (e:1009–1021).

    Returns a dict with ok, src, and either the registration fields or why.
    A failed Reading is reported as ok=False (same meaning as legacy None).
    """
    src = "asterisk -rx 'pjsip show registrations'"
    reading = transport.asterisk("pjsip show registrations")
    if not reading.ok:
        return {"ok": False, "src": src, "why": "asterisk CLI not reachable"}
    txt = reading.text
    for line in txt.splitlines():
        m = re.match(
            r"\s*(\S+)/(\S+)\s+(\S+)\s+(Registered|Unregistered|Rejected)"
            r"\s*(\(exp\. (\d+)s\))?",
            line,
        )
        if m:
            return {
                "ok": True,
                "src": src,
                "name": m.group(1),
                "uri": m.group(2),
                "status": m.group(4),
                "expires": m.group(6),
                "raw": txt.strip(),
            }
    return {"ok": True, "src": src, "status": None, "raw": txt.strip(),
            "why": "no registration row in output"}


def read_calls(
    transport: Transport,
    vty_fn: Callable[[Any, str], str] | None = None,
) -> dict[str, Any]:
    """Port of legacy read_calls (e:1024–1104).

    The cellular-core instrument (vty(MSC_VTY, "show connection")) is behind
    ``vty_fn``.  When vty_fn is None the MSC instrument is "not probed"
    (ok=False, as if the call raised).
    """
    out: dict[str, Any] = {"instruments": [], "subscribers": {}}
    reading = transport.asterisk("core show channels")
    if not reading.ok:
        out["instruments"].append({
            "name": "Asterisk channels", "ok": False,
            "src": "asterisk -rx 'core show channels'",
            "why": "asterisk CLI not reachable",
        })
    else:
        txt = reading.text
        m = re.search(r"(\d+) active calls?", txt)
        p = re.search(r"(\d+) calls? processed", txt)
        out["instruments"].append({
            "name": "Asterisk channels", "ok": True,
            "src": "asterisk -rx 'core show channels'",
            "value": int(m.group(1)) if m else None,
            "note": f"{p.group(1)} calls processed since start" if p else None,
            "raw": txt.strip(),
        })

    if vty_fn is not None:
        try:
            t = vty_fn(None, "show connection")
            blocks = re.split(r"^\s*Connection #\d+:", t, flags=re.M)[1:]
            subs: dict[str, Any] = {}
            for b in blocks:
                msisdn = re.search(r"MSISDN-(\d+)", b)
                state = re.search(r"RAN connection state: (\S+)", b)
                tags = sorted(set(re.findall(r"Use count: \d+ \(([^)]*)\)", b)))
                if msisdn:
                    subs[msisdn.group(1)] = {
                        "state": state.group(1) if state else None,
                        "tags": tags, "in_call": "cc" in tags,
                    }
            inst: dict[str, Any] = {
                "name": "MSC connections", "ok": True,
                "src": "cell-core vty 4254: show connection",
                "raw": t.strip() or "(no output -- no connections)",
                "value": len(blocks),
            }
            if blocks:
                ncc = sum(1 for v in subs.values() if v["in_call"])
                inst["note"] = (
                    f"{ncc} of {len(blocks)} carrying call-control; the "
                    f"rest are signalling only (location update, SMS)"
                )
            out["subscribers"] = subs
            out["instruments"].append(inst)
        except Exception as e:
            out["instruments"].append({
                "name": "MSC connections", "ok": False,
                "src": "cell-core vty 4254: show connection",
                "why": str(e),
            })
    else:
        out["instruments"].append({
            "name": "MSC connections", "ok": False,
            "src": "cell-core vty 4254: show connection",
            "why": "not probed",
        })

    by = {i["name"]: i for i in out["instruments"]}
    a = by.get("Asterisk channels", {})
    mc = by.get("MSC connections", {})
    out["value"] = a.get("value") if a.get("ok") else None
    out["cellular"] = mc.get("value") if mc.get("ok") else None
    out["impossible"] = (
        out["value"] is not None
        and out["cellular"] is not None
        and out["cellular"] > out["value"]
    )
    return out


def read_sip_endpoints(transport: Transport) -> dict[str, Any]:
    """Port of legacy read_sip_endpoints (e:1108–1136)."""
    src = "asterisk -rx 'pjsip show endpoints'"
    reading = transport.asterisk("pjsip show endpoints")
    if not reading.ok:
        return {"ok": False, "src": src, "why": "asterisk CLI not reachable"}
    txt = reading.text
    rows: list[dict[str, Any]] = []
    cur: dict[str, Any] | None = None
    for line in txt.splitlines():
        m = re.match(
            r"\s*Endpoint:\s+(\S+?)(?:/\S*)?\s+(\S+(?: \S+)*?)\s+(\d+) of",
            line,
        )
        if m:
            cur = {
                "ext": m.group(1),
                "state": m.group(2).strip(),
                "channels": int(m.group(3)),
                "contact": None,
            }
            rows.append(cur)
            continue
        m2 = re.match(r"\s*Contact:\s+\S+/(\S+)\s+\S+\s+(\S+)\s", line)
        if m2 and cur:
            cur["contact"] = {"uri": m2.group(1), "status": m2.group(2)}
    return {
        "ok": True,
        "src": src,
        "rows": [r for r in rows if r["ext"].isdigit()],
        "infra": [r for r in rows if not r["ext"].isdigit()],
    }

"""faxconsole.routes — pure request handler.

``handle(method, path, headers, body, transport, config)`` is a pure
function: it receives a request and returns a Response.  No sockets, no
globals.  The http.server adapter in server.py calls it.

Routes implemented:
  GET  /api/fax/status       — faxcli status JSON
  GET  /api/fax/log?limit=N  — faxcli log JSON
  GET  /api/fax              — legacy combined shape (fax_state)
  GET  /api/pbx/trunk        — read_trunk dict
  GET  /api/pbx/calls        — read_calls dict
  GET  /api/pbx/endpoints    — read_sip_endpoints dict
  POST /api/fax/send         — multipart PDF upload
  GET  /api/version          — realm-sigil contract
  *    anything else          — 404 with escaped path

Write gate: X-Auth-Token header checked with hmac.compare_digest (legacy
write_authorized, e:2914–2951).  Fails closed when no token is configured.
"""
from __future__ import annotations

import argparse
import datetime
import hmac
import io
import json
import os
import platform
import re
import socket
import sys
import time
from dataclasses import dataclass
from typing import Any
from urllib.parse import parse_qs, urlparse

from faxcli import cdr as cdr_mod
from faxcli import cli as cli_mod
from faxcli.models import LogResult, LogRow, StatusResult
from faxcli.transport import Transport
from faxconsole.pbx import read_calls, read_sip_endpoints, read_trunk
from faxconsole.version import version_dict

# ---------------------------------------------------------------------------
# Constants (portable defaults; __main__ can inject a Config)
# ---------------------------------------------------------------------------

FAX_MAX_BYTES = 15 * 1024 * 1024  # 15 MB, matching legacy e:2007


# ---------------------------------------------------------------------------
# Response dataclass
# ---------------------------------------------------------------------------

@dataclass
class Response:
    """An HTTP response ready to be serialised."""

    status: int
    body: bytes
    content_type: str = "application/json"


def _json_response(status: int, obj: Any) -> Response:
    return Response(status=status, body=json.dumps(obj).encode())


def _ok(obj: Any) -> Response:
    return _json_response(200, obj)


def _bad(obj: Any) -> Response:
    return _json_response(400, obj)


def _err(code: int, obj: Any) -> Response:
    return _json_response(code, obj)


# ---------------------------------------------------------------------------
# HTML escaper (port of legacy html_escape e:2656–2702)
# ---------------------------------------------------------------------------

def _html_escape(t: str) -> str:
    return (
        str(t)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace('"', "&quot;")
        .replace("'", "&#39;")
    )


# ---------------------------------------------------------------------------
# Multipart parser (port of legacy _multipart e:2040–2055)
# ---------------------------------------------------------------------------

def _multipart(content_type: str, body: bytes) -> tuple[dict, dict]:
    """(fields, files) from a multipart/form-data body."""
    from email.parser import BytesParser  # noqa: PLC0415
    from email.policy import default  # noqa: PLC0415

    msg = BytesParser(policy=default).parsebytes(
        b"Content-Type: " + content_type.encode() + b"\r\n\r\n" + body
    )
    fields: dict[str, str] = {}
    files: dict[str, tuple[str, bytes]] = {}
    for part in msg.iter_parts():
        name = part.get_param("name", header="content-disposition") or ""
        fn = part.get_filename()
        payload = part.get_payload(decode=True) or b""
        if fn:
            files[name] = (fn, payload)
        else:
            fields[name] = payload.decode("utf-8", "replace").strip()
    return fields, files


# ---------------------------------------------------------------------------
# Write-token gate (port of legacy write_authorized e:2914–2951)
# ---------------------------------------------------------------------------

def _write_token(config: "Config") -> str:
    """Expected token: from Config, then env (like legacy write_token e:2651–2653)."""
    tok = config.write_token if config.write_token is not None else ""
    if not tok:
        tok = os.environ.get("TELEPHONY_CONSOLE_TOKEN", "")
    return tok.strip()


def _write_authorized(headers: dict[str, str], config: "Config") -> Response | None:
    """Return a 401 Response if the write token check fails, else None.

    Fails closed when no token is configured (legacy e:2928–2938).
    """
    expected = _write_token(config)
    supplied = (headers.get("x-auth-token") or "").strip()
    if not expected:
        return _err(401, {
            "ok": False,
            "detail": (
                "write refused: this server has no write token configured. "
                "Set TELEPHONY_CONSOLE_TOKEN in the environment."
            ),
        })
    if not hmac.compare_digest(supplied.encode("utf-8"), expected.encode("utf-8")):
        return _err(401, {"ok": False, "detail": "write refused: missing or incorrect X-Auth-Token."})
    return None


# ---------------------------------------------------------------------------
# Config
# ---------------------------------------------------------------------------

@dataclass
class Config:
    """Runtime configuration injected into handle()."""

    transport: Transport
    inbox: str = "/var/lib/faxconsole/fax"
    spool: str = "/var/spool/asterisk/fax"
    max_bytes: int = FAX_MAX_BYTES
    write_token: str | None = None  # if None, falls back to env
    replay: bool = False            # replay mode: POST /api/fax/send → dry run


# ---------------------------------------------------------------------------
# Route implementations
# ---------------------------------------------------------------------------

def _route_status(config: Config) -> Response:
    """GET /api/fax/status — faxcli cmd_status result as JSON."""
    a = argparse.Namespace(json=True)
    buf = io.StringIO()
    cli_mod.cmd_status(a, config.transport, buf)
    text = buf.getvalue().strip()
    try:
        obj = json.loads(text.splitlines()[-1])
    except Exception as e:
        return _err(500, {"ok": False, "why": f"unparseable status output: {e}"})
    return _ok(obj)


def _route_log(path: str, config: Config) -> Response:
    """GET /api/fax/log?limit=N — faxcli cmd_log result as JSON."""
    qs = parse_qs(urlparse(path).query)
    try:
        limit = int(qs.get("limit", ["20"])[0])
    except (ValueError, IndexError):
        limit = 20
    a = argparse.Namespace(json=True, limit=limit)
    buf = io.StringIO()
    cli_mod.cmd_log(a, config.transport, buf)
    text = buf.getvalue().strip()
    try:
        obj = json.loads(text.splitlines()[-1])
    except Exception as e:
        return _err(500, {"ok": False, "why": f"unparseable log output: {e}"})
    return _ok(obj)


def _route_fax_state(config: Config) -> Response:
    """GET /api/fax — legacy combined shape (fax_state e:2030–2037)."""
    # Get status
    a_st = argparse.Namespace(json=True)
    buf_st = io.StringIO()
    cli_mod.cmd_status(a_st, config.transport, buf_st)
    try:
        st: dict = json.loads(buf_st.getvalue().strip().splitlines()[-1])
    except Exception as e:
        st = {"ok": False, "why": f"unparseable status: {e}"}

    # Get log (25 rows, matching legacy fax_state e:2032)
    a_lg = argparse.Namespace(json=True, limit=25)
    buf_lg = io.StringIO()
    cli_mod.cmd_log(a_lg, config.transport, buf_lg)
    try:
        lg: dict = json.loads(buf_lg.getvalue().strip().splitlines()[-1])
    except Exception as e:
        lg = {"ok": False, "why": f"unparseable log: {e}", "rows": []}

    result = {
        "ok": bool(st.get("ok")) and bool(lg.get("ok")),
        "status": st,
        "log": lg.get("rows", []),
        "why": st.get("why") or lg.get("why"),
        "src": "faxcli --local --json status | log --limit 25",
        "spool": config.spool,
        "inbox": config.inbox,
    }
    return _ok(result)


def _route_pbx_trunk(config: Config) -> Response:
    """GET /api/pbx/trunk."""
    return _ok(read_trunk(config.transport))


def _route_pbx_calls(config: Config) -> Response:
    """GET /api/pbx/calls."""
    return _ok(read_calls(config.transport))


def _route_pbx_endpoints(config: Config) -> Response:
    """GET /api/pbx/endpoints."""
    return _ok(read_sip_endpoints(config.transport))


def _route_send(headers: dict[str, str], body: bytes, config: Config) -> Response:
    """POST /api/fax/send — port of legacy do_POST /api/fax/send (e:2958–2974)."""
    # Write gate
    auth_err = _write_authorized(headers, config)
    if auth_err is not None:
        return auth_err

    # Size cap (legacy e:2960–2961: Content-Length > FAX_MAX_BYTES + 65536)
    try:
        content_length = int(headers.get("content-length") or len(body))
    except (ValueError, TypeError):
        content_length = len(body)
    if content_length > config.max_bytes + 65536:
        return _err(413, {"ok": False, "detail": "upload too large (15 MB max)"})

    ctype = headers.get("content-type", "")
    if not ctype.startswith("multipart/form-data"):
        return _bad({"ok": False, "detail": "expected multipart/form-data"})

    try:
        fields, files = _multipart(ctype, body)
    except Exception as e:
        return _bad({"ok": False, "detail": f"bad body: {e}"})

    if fields.get("confirm") != "yes":
        return _bad({
            "ok": False,
            "detail": (
                "refused: this dials a real number and delivers a document, "
                "so it requires an explicit confirmation"
            ),
        })

    result = _fax_send(fields, files, config)
    return _json_response(200 if result.get("ok") else 400, result)


def _fax_send(fields: dict, files: dict, config: Config) -> dict[str, Any]:
    """Port of legacy fax_send (e:2058–2090), calling faxcli directly."""
    from faxcli.numbers import InvalidNumber, normalize  # noqa: PLC0415

    # Validate number (legacy e:2060–2066)
    raw_number = fields.get("number", "")
    try:
        number = normalize(raw_number)
    except InvalidNumber as exc:
        return {"ok": False, "detail": str(exc)}

    # Must have a file
    if "file" not in files:
        return {"ok": False, "detail": "no PDF attached"}
    fn, data = files["file"]

    # PDF check (legacy e:2070–2071)
    if not data.startswith(b"%PDF-"):
        return {"ok": False, "detail": "only PDF files are accepted"}

    # Size cap (legacy e:2072–2073)
    if len(data) > config.max_bytes:
        return {"ok": False, "detail": "PDF larger than 15 MB"}

    # Build label (legacy e:2074)
    raw_label = fields.get("label") or os.path.splitext(fn)[0]
    label = re.sub(r"[^A-Za-z0-9_-]+", "-", raw_label)[:40] or "fax"

    # Write PDF to inbox (legacy e:2075–2082)
    try:
        os.makedirs(config.inbox, exist_ok=True)
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")  # noqa: DTZ005
        path = os.path.join(config.inbox, f"{stamp}-{label}.pdf")
        with open(path, "wb") as fh:
            fh.write(data)
    except OSError as e:
        return {"ok": False, "detail": f"could not store the PDF: {e}"}

    # In replay mode, always dry-run (design requirement)
    if config.replay:
        a = argparse.Namespace(
            json=True,
            number=number,
            pdf=path,
            label=label,
            dry_run=True,
            wait=0,
            local=True,
        )
        buf = io.StringIO()
        ret = cli_mod.cmd_send(a, config.transport, buf)
        try:
            r: dict = json.loads(buf.getvalue().strip().splitlines()[-1])
        except Exception as e:
            return {"ok": False, "detail": f"unparseable send output: {e}"}
        if not r.get("ok"):
            return {"ok": False, "detail": r.get("why") or "the fax CLI refused"}
        r["replay"] = True
        r["detail"] = "replay: nothing is dialled"
        r["pdf"] = path
        return r

    # Real send (legacy e:2083–2090)
    a = argparse.Namespace(
        json=True,
        number=number,
        pdf=path,
        label=label,
        dry_run=False,
        wait=0,
        local=True,
    )
    buf = io.StringIO()
    ret = cli_mod.cmd_send(a, config.transport, buf)
    try:
        r = json.loads(buf.getvalue().strip().splitlines()[-1])
    except Exception as e:
        return {"ok": False, "detail": f"unparseable send output: {e}"}
    if not r.get("ok"):
        return {"ok": False, "detail": r.get("why") or "the fax CLI refused"}
    r["detail"] = (
        "dialing %s with %s page(s); the outcome appears in the log below when the "
        "call ends (judged by the fax counters, not the call disposition)"
        % (number, r.get("pages", "?"))
    )
    r["pdf"] = path
    return r


def _route_version() -> Response:
    """GET /api/version — realm-sigil contract."""
    return _ok(version_dict())


def _route_not_found(path: str) -> Response:
    """404 with HTML-escaped path (legacy e:2907–2911)."""
    escaped = _html_escape(path)
    body = json.dumps({
        "ok": False,
        "status": 404,
        "detail": f"No such route: {escaped}",
    })
    return Response(status=404, body=body.encode())


# ---------------------------------------------------------------------------
# Main dispatcher
# ---------------------------------------------------------------------------

def handle(
    method: str,
    path: str,
    headers: dict[str, str],
    body: bytes,
    config: Config,
) -> Response:
    """Pure request dispatcher.  No sockets, no globals.

    ``headers`` keys are lowercased by the caller (server.py normalises them).
    """
    # Normalise method to upper case
    method = method.upper()

    # Strip query string for route matching
    parsed = urlparse(path)
    route = parsed.path

    if method == "GET":
        if route == "/api/fax/status":
            return _route_status(config)
        if route == "/api/fax/log":
            return _route_log(path, config)
        if route == "/api/fax":
            return _route_fax_state(config)
        if route == "/api/pbx/trunk":
            return _route_pbx_trunk(config)
        if route == "/api/pbx/calls":
            return _route_pbx_calls(config)
        if route == "/api/pbx/endpoints":
            return _route_pbx_endpoints(config)
        if route == "/api/version":
            return _route_version()

    if method == "POST":
        if route == "/api/fax/send":
            return _route_send(headers, body, config)

    return _route_not_found(path)

"""tests/test_faxconsole_routes.py — route-level tests through handle().

Every route is exercised against a ReplayTransport backed by the existing
fixtures.  No TCP port is opened.  The send tests are in
test_faxconsole_send.py; this file focuses on read routes and the 404.
"""
from __future__ import annotations

import json
from pathlib import Path

import pytest

from faxcli.transport import ReplayTransport
from faxconsole.routes import Config, Response, handle

FIXTURE_DIR = Path("tests/fixtures")


def _transport(**kwargs) -> ReplayTransport:
    return ReplayTransport(
        fixture_dir=FIXTURE_DIR / "asterisk",
        cdr_path=FIXTURE_DIR / "cdr" / "Master.csv",
        **kwargs,
    )


def _config(**kwargs) -> Config:
    defaults = {"transport": _transport(), "inbox": "/tmp/faxconsole-inbox-test",
                "spool": "/var/spool/asterisk/fax"}
    defaults.update(kwargs)
    return Config(**defaults)


def _get(path: str, config: Config | None = None) -> Response:
    return handle("GET", path, {}, b"", config or _config())


# ---------------------------------------------------------------------------
# GET /api/fax/status
# ---------------------------------------------------------------------------

class TestStatusRoute:
    def test_status_code_200(self):
        r = _get("/api/fax/status")
        assert r.status == 200

    def test_content_type_json(self):
        r = _get("/api/fax/status")
        assert r.content_type == "application/json"

    def test_body_is_valid_json(self):
        r = _get("/api/fax/status")
        obj = json.loads(r.body)
        assert isinstance(obj, dict)

    def test_has_required_fields(self):
        obj = json.loads(_get("/api/fax/status").body)
        for field in ("ok", "spandsp", "trunk_registered", "trunk_available",
                      "obi100_registered", "active_sessions", "stats", "gs"):
            assert field in obj, f"missing field: {field}"

    def test_ok_true_with_good_fixtures(self):
        obj = json.loads(_get("/api/fax/status").body)
        assert obj["ok"] is True

    def test_stats_is_dict(self):
        obj = json.loads(_get("/api/fax/status").body)
        assert isinstance(obj["stats"], dict)

    def test_active_sessions_is_list(self):
        obj = json.loads(_get("/api/fax/status").body)
        assert isinstance(obj["active_sessions"], list)

    def test_matches_golden(self):
        golden = json.loads((FIXTURE_DIR / "golden" / "status.json").read_text())
        obj = json.loads(_get("/api/fax/status").body)
        # Every field in the golden must be present and equal
        for k, v in golden.items():
            assert obj[k] == v, f"field {k!r}: got {obj[k]!r}, want {v!r}"

    def test_ok_false_when_asterisk_fails(self):
        """When all asterisk readings fail, ok must be False."""
        failing_transport = ReplayTransport(
            fixture_dir=FIXTURE_DIR / "asterisk",
            cdr_path=FIXTURE_DIR / "cdr" / "Master.csv",
            fail_commands={
                "fax show stats", "fax show sessions",
                "pjsip show endpoint voipms-fax", "pjsip show registrations",
                "pjsip show endpoint 2007", "module show like res_fax",
            },
        )
        cfg = _config(transport=failing_transport)
        obj = json.loads(_get("/api/fax/status", cfg).body)
        assert obj["ok"] is False


# ---------------------------------------------------------------------------
# GET /api/fax/log
# ---------------------------------------------------------------------------

class TestLogRoute:
    def test_status_code_200(self):
        r = _get("/api/fax/log")
        assert r.status == 200

    def test_body_has_ok_and_rows(self):
        obj = json.loads(_get("/api/fax/log").body)
        assert "ok" in obj
        assert "rows" in obj
        assert isinstance(obj["rows"], list)

    def test_default_limit(self):
        obj = json.loads(_get("/api/fax/log").body)
        assert len(obj["rows"]) <= 20

    def test_custom_limit(self):
        obj = json.loads(_get("/api/fax/log?limit=3").body)
